"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["7590"],{4114(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>a,contentTitle:()=>o,toc:()=>l,assets:()=>c});var n=JSON.parse('{"id":"contributors/DESIGN-PRINCIPLES","title":"StrayMark \u2014 Design Principles","description":"Version internal references to Sentinel artifacts are generalized; Plan \u2192 Charter rename in going-forward vocabulary)","source":"@site/../docs/contributors/DESIGN-PRINCIPLES.md","sourceDirName":"contributors","slug":"/contributors/DESIGN-PRINCIPLES","permalink":"/straymark/docs/contributors/DESIGN-PRINCIPLES","draft":false,"unlisted":false,"editUrl":"https://github.com/StrangeDaysTech/straymark/edit/main/docs/contributors/DESIGN-PRINCIPLES.md","tags":[],"version":"current","frontMatter":{},"sidebar":"docsSidebar","previous":{"title":"Contributors","permalink":"/straymark/docs/category/contributors"},"next":{"title":"Contributors documentation","permalink":"/straymark/docs/contributors/"}}'),r=i(4848),s=i(8453);let a={},o="StrayMark \u2014 Design Principles",c={},l=[{value:"Why this document exists",id:"why-this-document-exists",level:2},{value:"1. The tool serves the craft, not the product",id:"1-the-tool-serves-the-craft-not-the-product",level:2},{value:"2. The primary user is the senior engineer orchestrating agents",id:"2-the-primary-user-is-the-senior-engineer-orchestrating-agents",level:2},{value:"3. Strict open source, no asterisks in the core",id:"3-strict-open-source-no-asterisks-in-the-core",level:2},{value:"4. Regulatory compliance is a side effect, not the product",id:"4-regulatory-compliance-is-a-side-effect-not-the-product",level:2},{value:"5. Schema-driven before feature-driven",id:"5-schema-driven-before-feature-driven",level:2},{value:"6. Cognitive discipline over raw productivity",id:"6-cognitive-discipline-over-raw-productivity",level:2},{value:"7. Local-first, Cloud as amplifier",id:"7-local-first-cloud-as-amplifier",level:2},{value:"8. Project memory lives in the repo, not in an external database",id:"8-project-memory-lives-in-the-repo-not-in-an-external-database",level:2},{value:"9. Simplicity over capability",id:"9-simplicity-over-capability",level:2},{value:"10. Honesty about what the tool does not do",id:"10-honesty-about-what-the-tool-does-not-do",level:2},{value:"11. The community takes care of the tool, not the other way around",id:"11-the-community-takes-care-of-the-tool-not-the-other-way-around",level:2},{value:"12. The product&#39;s velocity is the velocity of learning",id:"12-the-products-velocity-is-the-velocity-of-learning",level:2},{value:"How to use this document",id:"how-to-use-this-document",level:2}];function h(e){let t={a:"a",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"straymark--design-principles",children:"StrayMark \u2014 Design Principles"})}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Version:"})," 0.2.2 (empirical annotations + editorial pass for public readability: internal references to Sentinel artifacts are generalized; Plan \u2192 Charter rename in going-forward vocabulary)\n",(0,r.jsx)(t.strong,{children:"Date:"})," 2026-05-02\n",(0,r.jsx)(t.strong,{children:"Author:"})," Jose Villase\xf1or Montfort \u2014 StrangeDaysTech\n",(0,r.jsx)(t.strong,{children:"Purpose:"})," Articulate the product philosophy in compact form, to serve as a reference against design decisions and as a criterion for saying no to features that don't fit.\n",(0,r.jsx)(t.strong,{children:"Languages:"})," English | ",(0,r.jsx)(t.a,{href:"../i18n/es/contributors/DESIGN-PRINCIPLES.md",children:"Espa\xf1ol"})," | ",(0,r.jsx)(t.a,{href:"../i18n/zh-CN/contributors/DESIGN-PRINCIPLES.md",children:"\u7B80\u4F53\u4E2D\u6587"})]}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"why-this-document-exists",children:"Why this document exists"}),"\n",(0,r.jsx)(t.p,{children:"Software products drift, over time, toward whatever incentive pushes them hardest. If the pressure is revenue, they drift toward features that sell. If the pressure is adoption, they drift toward features that go viral. If the pressure is competition, they drift toward parity with the most visible competitor. Each of those drifts is individually rational and collectively destructive: the product loses its original shape and becomes another averaged-out point in the market."}),"\n",(0,r.jsxs)(t.p,{children:["This document exists so StrayMark has an explicit anchor. Future decisions must be checkable against these principles. A feature that violates a principle may still be a good idea, but it requires a deliberate conversation about ",(0,r.jsx)(t.em,{children:"which"})," principle is being relaxed and ",(0,r.jsx)(t.em,{children:"why"}),". The existence of the document doesn't guarantee discipline; the conscious question it forces, does."]}),"\n",(0,r.jsx)(t.p,{children:"The principles are ranked by hierarchy: when two conflict, the earlier one wins."}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Version 0.2 \u2014 empirical annotations."})," This version incorporates lessons from the first experiment that stresses the principles against evidence: six execution cycles on a real adopter project (Sentinel \u2014 a Go backend system), with three iterations of the Charter format (v1 \u2192 v2 \u2192 v3) and two dual external audits per cycle. The annotations per principle concentrate on the three the experiment exercised directly (#6, #9, #12); the hierarchy and the wording of the twelve principles do not change. The detailed evidence lives in ",(0,r.jsx)(t.code,{children:"straymark-thesis-validation.md"})," (preserved in ",(0,r.jsx)(t.code,{children:"docs/decisions/proposals/"})," for historical reference)."]}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"1-the-tool-serves-the-craft-not-the-product",children:"1. The tool serves the craft, not the product"}),"\n",(0,r.jsx)(t.p,{children:"StrayMark exists so that the engineer working with AI agents produces work they're proud of. That is the final metric. Any feature that improves adoption, retention, or revenue metrics at the cost of degrading the quality of the user's work is a feature that violates the foundational principle."}),"\n",(0,r.jsxs)(t.p,{children:["In practice, this means decisions are made with the question ",(0,r.jsx)(t.em,{children:'"does this help the engineer do better engineering?"'}),", not with the question ",(0,r.jsx)(t.em,{children:'"does this grow the product?"'}),". The two questions sometimes converge and sometimes don't. When they diverge, the first wins."]}),"\n",(0,r.jsx)(t.h2,{id:"2-the-primary-user-is-the-senior-engineer-orchestrating-agents",children:"2. The primary user is the senior engineer orchestrating agents"}),"\n",(0,r.jsx)(t.p,{children:"Not the VP Engineering. Not the CISO. Not the compliance officer. The primary user is the engineer with strong technical judgment who uses AI agents to work on projects they couldn't realistically tackle alone, and who needs externalized cognitive discipline so the agent doesn't introduce systemic chaos."}),"\n",(0,r.jsx)(t.p,{children:"Features are designed for that person. Flows are optimized for that person. Documentation is written for that person. When other people (compliance officers, managers, auditors) eventually use the product, they do so on a foundation that respects the engineer first. Inverting this hierarchy is the most common cause of developer-tooling products turning bad."}),"\n",(0,r.jsx)(t.h2,{id:"3-strict-open-source-no-asterisks-in-the-core",children:"3. Strict open source, no asterisks in the core"}),"\n",(0,r.jsx)(t.p,{children:'The framework, the CLI, and the TUI are and always will be open-source under a permissive license. No capped features in the OSS to push toward paid tiers. No mandatory telemetry. No account requirement for full use. No "community edition" inferior in core capabilities to an "enterprise edition".'}),"\n",(0,r.jsx)(t.p,{children:"When a commercial layer eventually exists (Cloud, hosting, services), it must offer genuinely additive value, not rescue functionality stripped from the OSS to manufacture demand. The difference between honest open-core and bait-and-switch open-core is honesty about what is added value vs. what is the tool itself."}),"\n",(0,r.jsx)(t.h2,{id:"4-regulatory-compliance-is-a-side-effect-not-the-product",children:"4. Regulatory compliance is a side effect, not the product"}),"\n",(0,r.jsx)(t.p,{children:'ISO/IEC 42001, EU AI Act, NIST AI RMF, GDPR are useful frameworks that give structure to documentation. StrayMark supports them as an optional layer because they are valuable for users who need them. But the product is not "a compliance tool". The product is an engineering tool that produces, as a side effect, evidence compatible with those frameworks.'}),"\n",(0,r.jsx)(t.p,{children:"This distinction matters because the compliance buyer and the engineer using the tool have different needs. When the product is positioned as compliance, design decisions skew toward the compliance buyer and degrade the engineer's flow. Keeping compliance as a side effect protects the quality of the primary flow."}),"\n",(0,r.jsx)(t.h2,{id:"5-schema-driven-before-feature-driven",children:"5. Schema-driven before feature-driven"}),"\n",(0,r.jsx)(t.p,{children:"The product's central entities (Stage Closure Bundle, Charter, Document) are defined first as formal schemas with strict versioning. Features are built against those schemas. This has three structural benefits: it lets multiple implementations coexist without coordinating, it makes evolution controlled and reversible, and it forces thinking about the contract before the implementation."}),"\n",(0,r.jsx)(t.p,{children:"The practical consequences are that breaking schema changes are rare and deliberate, that schemas are first-class product documentation, and that features that require violating a schema must first propose the schema's evolution."}),"\n",(0,r.jsx)(t.h2,{id:"6-cognitive-discipline-over-raw-productivity",children:"6. Cognitive discipline over raw productivity"}),"\n",(0,r.jsxs)(t.p,{children:["StrayMark does not compete with tools that promise ",(0,r.jsx)(t.em,{children:'"write code 10\xd7 faster with AI"'}),". It competes, if it competes with anything, against the chaos that fast AI code generates in serious projects. The metric that matters is not raw agent speed but sustained quality of the system produced."]}),"\n",(0,r.jsx)(t.p,{children:"This means features that add justified friction (validations, gates, documentation requirements, pre-work before planning) are acceptable and sometimes desirable. Features that promise to remove friction at the cost of the agent's reasoning quality are suspect by default."}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"v0.2 annotation \u2014 virtue vs. ceremony distinction."})," Empirical evidence revealed that not all friction in the flow has the same character. Friction is ",(0,r.jsx)(t.em,{children:"virtuous"})," when it externalizes public signal verifiable by third parties: formally naming risks that emerge during execution makes heterogeneous external auditors capture them; a drift-check at work closure detects declared-vs-modified file mismatches with zero false positives in empirical validation; dual auditing with two heterogeneous models calibrates cross-model and catches gaps a single auditor misses. Friction is ",(0,r.jsx)(t.em,{children:"attackable ceremony"})," when it only generates manual triage or prescribes without allowing context adaptation: a rigid template that clashes with the destination module's convention, or a drift-check alerting on divergences already documented elsewhere, are the two observed cases. The first is preserved; the second is a format bug, not a virtue of the principle. Detailed evidence and actionable criteria live in ",(0,r.jsx)(t.code,{children:"straymark-thesis-validation.md"})," \xa75 (preserved in ",(0,r.jsx)(t.code,{children:"docs/decisions/proposals/"}),")."]}),"\n",(0,r.jsx)(t.h2,{id:"7-local-first-cloud-as-amplifier",children:"7. Local-first, Cloud as amplifier"}),"\n",(0,r.jsx)(t.p,{children:"The CLI works completely, without network, in the local repo. That is the first experience and the foundation everything builds on. Cloud exists to amplify value (cross-repo aggregation, signed evidence, semantic historical search, team collaboration) but never to replace the CLI or turn it into a thin client."}),"\n",(0,r.jsx)(t.p,{children:"A user who never connects to Cloud must still get most of the product's value. This protects the tool against Cloud failure modes, against business-model changes, and against the classic drift of products that start local and end up requiring mandatory connection."}),"\n",(0,r.jsx)(t.h2,{id:"8-project-memory-lives-in-the-repo-not-in-an-external-database",children:"8. Project memory lives in the repo, not in an external database"}),"\n",(0,r.jsxs)(t.p,{children:["AILOGs, ADRs, AIDECs, Charters, and bundles live as versioned files alongside the code. The reason is structural: project memory must outlive the product that generated it. If StrayMark disappears tomorrow, the ",(0,r.jsx)(t.code,{children:".straymark/"})," files remain readable, parseable, and useful because they are structured markdown and JSON conforming to public schemas."]}),"\n",(0,r.jsx)(t.p,{children:"This decision gives up some capabilities that would be easier with a centralized backend (for example, instant full-text search without sync), but gains long-term reliability and user control over their own data. The asymmetry is deliberate and permanent."}),"\n",(0,r.jsx)(t.h2,{id:"9-simplicity-over-capability",children:"9. Simplicity over capability"}),"\n",(0,r.jsx)(t.p,{children:"When two designs meet the same goal, the simpler one wins. When a feature is genuinely useful but requires significant complexity, it's better to wait until the usage pattern is validated in at least three real projects before crystallizing it into the product."}),"\n",(0,r.jsx)(t.p,{children:"This applies to both the product and the product's language. Command names, document types, and framework concepts are chosen to be immediately understandable, not to sound technically sophisticated. If a concept requires lengthy explanation for a new user, it's probably poorly designed."}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"v0.2 annotation \u2014 bash before framework when bash suffices."}),' Empirical evidence demonstrated that a ~145-line bash script (awk + grep + git) covers the "drift between declared and modified files" case with zero false positives across two tests. The conscious decision not to implement it initially in the CLI\'s language (Rust) is justified thus: bash is zero-build, no additional dependencies, inspectable in place; maintenance cost is low. When porting to the CLI in phase 2 of the roadmap (',(0,r.jsx)(t.code,{children:"straymark-cli-roadmap.md"}),", preserved in ",(0,r.jsx)(t.code,{children:"docs/decisions/proposals/"}),"), preserve the bash simplicity where possible \u2014 invoke the shell from Rust or reimplement carefully without inflating the logic. Complexity crystallizes only when the usage pattern demands it, not by default."]}),"\n",(0,r.jsx)(t.h2,{id:"10-honesty-about-what-the-tool-does-not-do",children:"10. Honesty about what the tool does not do"}),"\n",(0,r.jsx)(t.p,{children:"StrayMark does not evaluate models. It is not an LLM gateway. It does not replace the engineer's judgment. It does not prevent all hallucinations. It does not automatically certify regulatory compliance. The product pages, documentation, and public communication are explicit about these limits."}),"\n",(0,r.jsx)(t.p,{children:"The reason is practical: users who adopt the tool with realistic expectations stick with it. Users who adopt it believing it does things it doesn't abandon it frustrated. Early honesty about the limits is a better marketing investment than broad promises."}),"\n",(0,r.jsx)(t.h2,{id:"11-the-community-takes-care-of-the-tool-not-the-other-way-around",children:"11. The community takes care of the tool, not the other way around"}),"\n",(0,r.jsx)(t.p,{children:"StrayMark users are typically engineers who know more than the product team about their own use cases. Contributions, issues, and feedback are treated with professional respect, and roadmap decisions are made incorporating that view. Not democratically (the product needs a coherent vision), but as serious input."}),"\n",(0,r.jsx)(t.p,{children:'This does not mean doing everything the community asks. It means explaining when "no" is said and why, keeping the conversation visible and public, and accepting that the product will be better off from the intelligent pressure of those who use it seriously than from the team\'s isolated decisions.'}),"\n",(0,r.jsx)(t.h2,{id:"12-the-products-velocity-is-the-velocity-of-learning",children:"12. The product's velocity is the velocity of learning"}),"\n",(0,r.jsx)(t.p,{children:"StrayMark must not advance faster than what we learn about how it is actually used. Crystallizing features prematurely, before having real usage data in at least three different projects, generates high maintenance costs over features that may be wrong. The patience to wait for evidence is discipline, not inaction."}),"\n",(0,r.jsx)(t.p,{children:"This translates into an explicit preference for: prototypes before features, observation before crystallization, stable schemas over changing features, and incremental evolution over large rewrites."}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"v0.2 annotation \u2014 the spirit of N\u22653 facing limited initial evidence."})," The empirical evidence available at the time of writing this version comes from a single adopter project, in a single domain (Go backend), with a single author. Applied literally, the principle would block any crystallization from that evidence. Applied in spirit \u2014 rigorous observation before crystallization, incremental evolution with real data \u2014 the available evidence covers three axes of structural diversity: (a) variable scale of the units of work (XS, S, M across five cycles), (b) format iteration under empirical pressure (v1 \u2192 v2 \u2192 v3, each derived from the previous cycle), (c) cross-model auditor calibration (two heterogeneous models converging to similar scores in the most stressed cycle). These six cycles \xd7 three formats \xd7 three scales are evidence equivalent to the N\u22653 the principle aims to protect."]}),"\n",(0,r.jsxs)(t.p,{children:["What remains undiversified is the domain. To preserve the principle in its operational form: any schema that crystallizes from that evidence is published as ",(0,r.jsx)(t.code,{children:"v0.json"})," with an ",(0,r.jsx)(t.em,{children:"experimental"})," mark. The transition to stable ",(0,r.jsx)(t.code,{children:"v1.0"})," requires validation with a second project in another domain (frontend, ML pipeline, infra-as-code). Any feature that depends on an assumption without evidence \u2014 like the conditional-approval assumption, which requires multi-actor flow that the available evidence did not exercise \u2014 is explicitly blocked until a project that does exercise it appears. See ",(0,r.jsx)(t.code,{children:"straymark-thesis-validation.md"})," \xa76 and \xa78 (preserved in ",(0,r.jsx)(t.code,{children:"docs/decisions/proposals/"}),") for the argument's development and the list of specific gaps per assumption."]}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Meta-meta pattern detected \u2014 format self-evolution."})," Empirical evidence revealed that the format improves itself: each Charter (Plan in historical terminology) executed generates data that refines the next format. This suggests extending the principle in future versions: the tool evolves with itself; each use is input for the next version. For now this is documented as observation, not as an additional principle, until a second project confirms the pattern."]}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"how-to-use-this-document",children:"How to use this document"}),"\n",(0,r.jsx)(t.p,{children:"When a non-trivial design decision arises, it is worth contrasting it explicitly against the twelve principles and recording the result. Three useful patterns:"}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Decisions that satisfy all principles"}),": proceed normally."]}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Decisions that conflict with one principle"}),": explicitly document which principle is being relaxed, why, and what evidence would lead to reverting the decision. This record should live in an AIDEC or ADR."]}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Decisions that violate foundational principles (1, 2, 3, 4)"}),": are not made without first reviewing whether the principle is still correct. If it is, the decision is discarded. If not, the principle is updated ",(0,r.jsx)(t.em,{children:"before"})," making the decision, not after."]}),"\n",(0,r.jsx)(t.p,{children:"The principles are formally reviewed every six months with the accumulated evidence. Changes between formal reviews are possible but must be deliberate and documented."}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.p,{children:(0,r.jsx)(t.em,{children:"This document is a guardrail, not a manual. Its usefulness is measured in how many times it makes us pause before making a decision we would later have regretted."})})]})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}},8453(e,t,i){i.d(t,{R:()=>a,x:()=>o});var n=i(6540);let r={},s=n.createContext(r);function a(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);